"""Minimal MD Parking JSON-RPC client.

Authentication material and signed stream capabilities are runtime secrets and
must never be included in exceptions or logs emitted by this module.
"""

from __future__ import annotations

import json
import os
import threading
import urllib.request
from dataclasses import asdict, dataclass
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import urlsplit


class ProviderError(RuntimeError):
    """Provider failure with a value safe to expose in diagnostics."""

    def __init__(self, message: str, safe_code: str = "provider_error") -> None:
        super().__init__(message)
        self.safe_code = safe_code


@dataclass(frozen=True, slots=True)
class Session:
    access_token: str
    refresh_token: str
    api_url: str


class Client:
    """Thread-safe client for the small confirmed provider contract."""

    def __init__(
        self,
        auth_url: str,
        app: object,
        client_id: str,
        fingerprint: str,
        allowed_hosts: tuple[str, ...] = ("auth.mdparking.ru", "app.mdparking.ru"),
    ) -> None:
        self._allowed_hosts = allowed_hosts
        self.auth_url = self._validated_https_url(auth_url)
        self.app = app
        self.client_id = client_id
        self.fingerprint = fingerprint
        self.session: Session | None = None
        self._request_id = 0
        self._lock = threading.RLock()

    def _validated_https_url(self, value: str) -> str:
        parts = urlsplit(value)
        if parts.scheme != "https" or not parts.hostname:
            raise ProviderError("provider URL is not HTTPS", "invalid_provider_url")
        hostname = parts.hostname.lower()
        if hostname not in self._allowed_hosts:
            raise ProviderError("provider host is not allowed", "invalid_provider_host")
        return value

    @staticmethod
    def _validated_stream_url(value: str) -> str:
        parts = urlsplit(value)
        hostname = (parts.hostname or "").lower()
        if parts.scheme != "rtsp" or not hostname.endswith(".mdparking.ru"):
            raise ProviderError("invalid stream response", "invalid_stream_url")
        return value

    def _rpc(
        self, url: str, method: str, params: dict, token: str | None = None
    ) -> object:
        url = self._validated_https_url(url)
        with self._lock:
            self._request_id += 1
            request_id = self._request_id

        body = json.dumps(
            {
                "params": params,
                "method": method,
                "jsonrpc": "2.0",
                "id": request_id,
            },
            separators=(",", ":"),
        ).encode("utf-8")
        headers = {
            "app-platform": "android",
            "Accept": "application/json, text/plain, */*",
            "Content-Type": "application/json",
            "User-Agent": "okhttp/4.9.2",
        }
        if token:
            headers["Authorization"] = f"Bearer {token}"
        request = urllib.request.Request(url, body, headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=20) as response:
                payload = json.loads(response.read())
        except HTTPError as exc:
            raise ProviderError(
                "provider HTTP request failed", f"http_{exc.code}"
            ) from exc
        except URLError as exc:
            reason = type(exc.reason).__name__
            raise ProviderError(
                "provider connection failed", f"network_{reason}"
            ) from exc
        except TimeoutError as exc:
            raise ProviderError("provider request timed out", "timeout") from exc
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise ProviderError("invalid provider JSON", "invalid_json") from exc

        if not isinstance(payload, dict):
            raise ProviderError("invalid provider JSON", "invalid_json_shape")
        error = payload.get("error")
        if error:
            code = error.get("code") if isinstance(error, dict) else "unknown"
            message = error.get("message") if isinstance(error, dict) else None
            if method == "getCode" and code == -32099 and message == "object required":
                raise ProviderError("object number required", "object_required")
            raise ProviderError("provider returned an error", f"rpc_{code}")
        return payload.get("result")

    def request_code(self, phone: str, object_id: str | None = None) -> object:
        params = {
            "phone": phone,
            "clientId": self.client_id,
            "fingerprint": self.fingerprint,
        }
        if object_id:
            params["objectId"] = object_id
        try:
            return self._rpc(self.auth_url, "getCode", params)
        except ProviderError as exc:
            if not object_id and exc.safe_code == "object_required":
                return {"objectRequired": True}
            raise

    def _session_from_result(self, result: object, error: str) -> Session:
        if not isinstance(result, dict) or not all(
            isinstance(result.get(key), str) and result.get(key)
            for key in ("accessToken", "refreshToken", "appServer")
        ):
            raise ProviderError(error, "invalid_session_response")
        return Session(
            result["accessToken"],
            result["refreshToken"],
            self._validated_https_url(result["appServer"]),
        )

    def authorize(self, phone: str, object_id: str, code: str) -> Session:
        result = self._rpc(
            self.auth_url,
            "authorization",
            {
                "phone": phone,
                "objectId": object_id,
                "code": code,
                "clientId": self.client_id,
                "app": self.app,
            },
        )
        session = self._session_from_result(result, "invalid authorization response")
        with self._lock:
            self.session = session
        return session

    def refresh_session(self) -> Session:
        with self._lock:
            current = self.session
        if current is None:
            raise ProviderError("not authorized", "not_authorized")
        result = self._rpc(
            self.auth_url,
            "updToken",
            {
                "refreshToken": current.refresh_token,
                "clientId": self.client_id,
                "app": self.app,
            },
            current.access_token,
        )
        session = self._session_from_result(result, "invalid refresh response")
        with self._lock:
            self.session = session
        return session

    def save_session(self, path: Path) -> None:
        with self._lock:
            session = self.session
        if session is None:
            raise ProviderError("not authorized", "not_authorized")
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
        try:
            temporary.write_text(json.dumps(asdict(session)), encoding="utf-8")
            temporary.chmod(0o600)
            temporary.replace(path)
            path.chmod(0o600)
        finally:
            temporary.unlink(missing_ok=True)

    def load_session(self, path: Path) -> bool:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (FileNotFoundError, OSError, UnicodeDecodeError, json.JSONDecodeError):
            return False
        if not isinstance(value, dict) or not all(
            isinstance(value.get(key), str) and value.get(key)
            for key in ("access_token", "refresh_token", "api_url")
        ):
            return False
        try:
            session = Session(
                value["access_token"],
                value["refresh_token"],
                self._validated_https_url(value["api_url"]),
            )
        except ProviderError:
            return False
        with self._lock:
            self.session = session
        return True

    def _current_session(self) -> Session:
        with self._lock:
            session = self.session
        if session is None:
            raise ProviderError("not authorized", "not_authorized")
        return session

    def inventory(self) -> list[dict]:
        session = self._current_session()
        result = self._rpc(
            session.api_url, "getObjects", {"id": "all"}, session.access_token
        )
        objects = result.get("objects", []) if isinstance(result, dict) else []
        return [item for item in objects if isinstance(item, dict)]

    def checkpoints(self, object_id: str) -> list[dict]:
        session = self._current_session()
        result = self._rpc(
            session.api_url,
            "getCheckpoints",
            {"id": object_id},
            session.access_token,
        )
        checkpoints = result.get("checkpoints", []) if isinstance(result, dict) else []
        return [item for item in checkpoints if isinstance(item, dict)]

    def access(self, acs_id: str) -> object:
        session = self._current_session()
        return self._rpc(
            session.api_url,
            "getAccess",
            {"acsId": acs_id},
            session.access_token,
        )

    def stream(self, channel: str) -> str:
        """Get a short-lived signed RTSP capability without exposing it."""
        session = self._current_session()
        result = self._rpc(
            session.api_url,
            "getStream",
            {"channel": channel},
            session.access_token,
        )
        if not isinstance(result, dict):
            raise ProviderError("invalid stream response", "invalid_stream_response")
        stream = result.get("stream")
        if isinstance(stream, str) and stream:
            return self._validated_stream_url(stream)
        if isinstance(stream, dict):
            for quality in ("hiRes", "lowRes"):
                source = stream.get(quality)
                if isinstance(source, str) and source:
                    return self._validated_stream_url(source)
        raise ProviderError("invalid stream response", "invalid_stream_response")
